  Kwon_allied?: boolean;
  Ward_available?: boolean;
  Rigg_available?: boolean;
  Pell_flipped?: boolean;
  Ren_viable?: boolean;

  // Access flags
  have_SafeConduct_route?: boolean;

  // Fear token input (computed elsewhere or estimated)
  FT_total?: number;
}

export interface SolverOutput {
  Act: ActBand;

  draftable: {
    C1: boolean; C2: boolean; C3: boolean; C4: boolean; C5: boolean; C6: boolean; C7: boolean;
    AddOnA: boolean; AddOnB: boolean;
  };

  MinBundle_draftable: boolean;

  FT_band: Band;
  ST_band: Band;
  ST_est: number;

  Quorum_ok: boolean;
  Trigger: Trigger;

  routeFeedback: {
    Eng_score: number;
    Legal_score: number;
    Venn_swing: number;
    hint: string;
  };
}

