  // Step 1: Act band
  let Act: ActBand;
  if (state.ED < 35 && state.SP <= 1 && state.WC >= 0 && state.RA === 2) Act = "COMPLACENT";
  else if (state.ED >= 70 || state.SP === 3 || state.WC <= -2 || state.RA === 0 || state.LM === 3) Act = "DESPERATE";
  else Act = "PARANOID";

  // Step 2: helper counts
  const M_count = (state.M_phys ? 1 : 0) + (state.M_sys ? 1 : 0) + (state.M_test ? 1 : 0);
  const S_any = state.S_legal || state.S_med || state.S_treaty;

