  const C1 = M_count >= 2;

  // Use your original permissive logic (can tighten to W_live && SUPP_proof)
  const C2 = (state.W_live || state.WC >= 0) && state.SUPP_proof;

  const C3 = state.L_custody;
  const C4 = state.M_sys || (state.M_phys && state.M_test);
  const C5 = state.S_med;
  const C6 = S_any;
  const C7 = state.V_leverage || state.S_treaty;

  const AddOnA = state.SEC_split;
  const AddOnB = state.K_direct && state.L_custody && (M_count >= 2) && state.W_live;

  const MinBundle_draftable = C1 && C2 && (C3 || C4) && C6 && C7;

