  const Vale = state.Vale_allied ? 1 : 0;
  const Oram = state.Oram_allied ? 1 : 0;
  const Venn = state.Venn_allied ? 1 : 0;
  const Kwon = state.Kwon_allied ? 1 : 0;
  const Ward = state.Ward_available ? 1 : 0;
  const Rigg = state.Rigg_available ? 1 : 0;
