  if (state.WC <= -2) ST_est -= 1;
  if (state.RA === 0) ST_est -= 1;
  ST_est = clamp(ST_est, 0, 8);

  const ST_band: Band = ST_est <= 2 ? "LOW" : (ST_est <= 5 ? "MID" : "HIGH");

  // Step 6: Quorum plausibility + trigger
  const haveSafeConduct = state.have_SafeConduct_route ?? false;
  const Quorum_ok = (state.WC > -3) && (state.SP < 3 || haveSafeConduct);

  let Trigger: Trigger = "NO";
  if (MinBundle_draftable && Quorum_ok) {
    if (FT_band === "HIGH" && ST_band === "LOW") Trigger = "OFFER_WITH_WARNING";
    else Trigger = "YES";
