  const Legal_score = (state.L_custody ? 1 : 0) + (state.S_med ? 1 : 0) + (state.S_legal ? 1 : 0) + (C3 ? 1 : 0) + (C6 ? 1 : 0);
  const Venn_swing = (state.V_leverage ? 1 : 0) + (state.S_treaty ? 1 : 0);

