  else if (Legal_score > Eng_score) hint = "Process case is strong. You still need mechanism proof for C1 (2-of-3).";
  else hint = "Balanced progress. Prioritize what your next Pressure Card makes feasible.";

  if (Venn_swing >= 1) hint += " Observer leverage can make the finale cleaner (C7) and soften Sato.";

