type ActBand = "COMPLACENT" | "PARANOID" | "DESPERATE";
type Band = "LOW" | "MID" | "HIGH";
type Trigger = "NO" | "OFFER_WITH_WARNING" | "YES";

type IncidentGrade =
  | "A1" | "A2" | "A3"
  | "B1" | "B2" | "B3"
  | "C1" | "C2" | "C3"
  | "D1" | "D2" | "D3";

export interface AttemptHistoryEntry {
  // Only what the solver needs for FT_incidents.
  A?: "A1" | "A2" | "A3";
  B?: "B1" | "B2" | "B3";
  C?: "C1" | "C2" | "C3";
  D?: "D1" | "D2" | "D3";
}

export interface CampaignState {
  attemptCount: number;

  // Globals
  ED: number; SB: number; CS: number; IF: number;
  SP: number; LM: number; WC: number;
  RA: 0 | 1 | 2;

  FABRICATION_KNOWN: boolean;
  EVASION_STIGMA: boolean;

  // Proof flags
  M_phys: boolean;
  M_sys: boolean;
  M_test: boolean;

  SUPP_proof: boolean;
  W_live: boolean;

  L_custody: boolean;

  S_legal: boolean;
  S_med: boolean;
  S_treaty: boolean;

  V_leverage: boolean;

  SEC_split: boolean;
  K_direct: boolean;

  // Allies (for ST_est; optional)
  Vale_allied?: boolean;
  Oram_allied?: boolean;
  Venn_allied?: boolean;
  Kwon_allied?: boolean;
  Ward_available?: boolean;
  Rigg_available?: boolean;
  Pell_flipped?: boolean;
  Ren_viable?: boolean;

  // Finale viability (recommended)
  EligibleVoters?: number;        // if undefined, solver falls back
  AccessToForum?: boolean;        // if undefined, solver falls back
  have_SafeConduct_route?: boolean;

  // Incident history for FT_incidents (recommended)
  // Put most recent attempt first: history[0] = last attempt.
  historyLast2?: AttemptHistoryEntry[];
}

export interface SolverOutput {
  Act: ActBand;

  draftable: {
    C1: boolean; C2: boolean; C3: boolean; C4: boolean; C5: boolean; C6: boolean; C7: boolean;
    AddOnA: boolean; AddOnB: boolean;
  };

  MinBundle_draftable: boolean;

  // Fear tokens (computed)
  FT_total: number;
  FT_band: Band;

  // Support estimate
  ST_est: number;
  ST_band: Band;

  // Finale viability + pacing
  Quorum_ok: boolean;
  Trigger: Trigger;

  routeFeedback: {
    Eng_score: number;
    Legal_score: number;
    Venn_swing: number;
    hint: string;
  };
}

const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));

function computeFTTotal(state: CampaignState): number {
  // Step 1 — base fear from ED (0–5)
  const FT_base = clamp(Math.floor(state.ED / 20), 0, 5);

  // Step 2 — force posture (0–3)
  const FT_SP = (state.SP - 1); // SP1=0, SP2=1, SP3=2
  const FT_LM = (state.LM === 3) ? 1 : 0;
  const FT_force = clamp(FT_SP + FT_LM, 0, 3);

  // Step 3 — unresolved incident pressure over last 2 attempts (0–4)
  const h = state.historyLast2 ?? [];
  const lastTwo = h.slice(0, 2);

  const hasA3 = lastTwo.some(e => e.A === "A3");
  const hasB3 = lastTwo.some(e => e.B === "B3");
  const hasC3 = lastTwo.some(e => e.C === "C3");
  const hasD2orD3 = lastTwo.some(e => e.D === "D2" || e.D === "D3");

  const FT_incidents =
    (hasA3 ? 1 : 0) +
    (hasB3 ? 1 : 0) +
    (hasC3 ? 1 : 0) +
    (hasD2orD3 ? 1 : 0);

  // Step 4 — reputation accelerants (0–3), then clamp
  let rep = 0;
  if (state.FABRICATION_KNOWN) rep += 2;
  if (state.EVASION_STIGMA) rep += 1;
  if (state.RA === 0) rep += 1;
  const FT_rep = clamp(rep, 0, 3);

  return clamp(FT_base + FT_force + FT_incidents + FT_rep, 0, 12);
}

export function solve(state: CampaignState): SolverOutput {
  // Step 1: Act band
  let Act: ActBand;
  if (state.ED < 35 && state.SP <= 1 && state.WC >= 0 && state.RA === 2) Act = "COMPLACENT";
  else if (state.ED >= 70 || state.SP === 3 || state.WC <= -2 || state.RA === 0 || state.LM === 3) Act = "DESPERATE";
  else Act = "PARANOID";

  // Helpers
  const M_count = (state.M_phys ? 1 : 0) + (state.M_sys ? 1 : 0) + (state.M_test ? 1 : 0);
  const S_any = state.S_legal || state.S_med || state.S_treaty;

  // Draftability (with stricter C2)
  const C1 = M_count >= 2;

  // Strict: if you can’t field a witness, restricting Security is much harder to justify procedurally.
  const C2 = state.W_live && state.SUPP_proof;

  const C3 = state.L_custody;
  const C4 = state.M_sys || (state.M_phys && state.M_test);
  const C5 = state.S_med;
  const C6 = S_any;
  const C7 = state.V_leverage || state.S_treaty;

  const AddOnA = state.SEC_split;
  const AddOnB = state.K_direct && state.L_custody && (M_count >= 2) && state.W_live;

  const MinBundle_draftable = C1 && C2 && (C3 || C4) && C6 && C7;

  // Fear (computed)
  const FT_total = computeFTTotal(state);
  const FT_band: Band = FT_total <= 3 ? "LOW" : (FT_total <= 7 ? "MID" : "HIGH");

  // Support estimate
  const Vale = state.Vale_allied ? 1 : 0;
  const Oram = state.Oram_allied ? 1 : 0;
  const Venn = state.Venn_allied ? 1 : 0;
  const Kwon = state.Kwon_allied ? 1 : 0;
  const Ward = state.Ward_available ? 1 : 0;
  const Rigg = state.Rigg_available ? 1 : 0;
  const Pell = state.Pell_flipped ? 1 : 0;
  const Ren = state.Ren_viable ? 1 : 0;

  let ST_est = Vale + Oram + Venn + Kwon + Ward + Rigg + Pell + Ren;
  if (state.WC <= -2) ST_est -= 1;
  if (state.RA === 0) ST_est -= 1;
  ST_est = clamp(ST_est, 0, 8);

  const ST_band: Band = ST_est <= 2 ? "LOW" : (ST_est <= 5 ? "MID" : "HIGH");

  // Step 6: Quorum plausibility
  const haveSafeConduct = state.have_SafeConduct_route ?? false;

  const Quorum_ok =
    (typeof state.EligibleVoters === "number" && typeof state.AccessToForum === "boolean")
      ? (state.EligibleVoters >= 8 && state.AccessToForum === true)
      : ((state.WC > -3) && (state.SP < 3 || haveSafeConduct)); // coarse fallback

  // Trigger
  let Trigger: Trigger = "NO";
  if (MinBundle_draftable && Quorum_ok) {
    Trigger = (FT_band === "HIGH" && ST_band === "LOW") ? "OFFER_WITH_WARNING" : "YES";
  }

  // Optional pacing lock
  if (Trigger !== "NO") {
    if (state.attemptCount < 6) Trigger = "NO";
    else if (state.attemptCount < 10 && Trigger === "YES") Trigger = "OFFER_WITH_WARNING";
  }

  // Route feedback
  const Eng_score = (state.M_sys ? 1 : 0) + (state.M_phys ? 1 : 0) + (state.M_test ? 1 : 0) + (C4 ? 1 : 0);
  const Legal_score = (state.L_custody ? 1 : 0) + (state.S_med ? 1 : 0) + (state.S_legal ? 1 : 0) + (C3 ? 1 : 0) + (C6 ? 1 : 0);
  const Venn_swing = (state.V_leverage ? 1 : 0) + (state.S_treaty ? 1 : 0);

  let hint = "";
  if (Eng_score > Legal_score) hint = "Close on mechanism. Shore up standing + minutes (C6/C7) and keep a live witness viable (C2).";
  else if (Legal_score > Eng_score) hint = "Process case is strong. You still need mechanism proof for C1 (2-of-3).";
  else hint = "Balanced progress. Prioritize what your next Pressure Card makes feasible.";

  if (Venn_swing >= 1) hint += " Observer leverage can make the finale cleaner (C7) and soften Sato.";

  return {
    Act,
    draftable: { C1, C2, C3, C4, C5, C6, C7, AddOnA, AddOnB },
    MinBundle_draftable,
    FT_total,
    FT_band,
    ST_est,
    ST_band,
    Quorum_ok,
    Trigger,
    routeFeedback: { Eng_score, Legal_score, Venn_swing, hint },
  };
}
